using namespace Aeostara;
std::filesystem::path fixtureDirectory;
std::string read(const std::string& path) { auto actual=std::filesystem::path(path);const auto local=fixtureDirectory/actual.filename();if(std::filesystem::exists(local))actual=local;std::ifstream stream(actual,std::ios::binary);if(!stream)throw std::runtime_error("Cannot read actual fixture source");std::ostringstream bytes;bytes<<stream.rdbuf();return bytes.str(); }
SemanticEnvironment environment(const Json& input,const std::string& authority) {return {read(input.at("mappingProfile").at("path").get<std::string>()),read(input.at("registryReferences").at("recognizedValidStates").at("path").get<std::string>()),read(input.at("registryReferences").at("fallback").at("path").get<std::string>()),authority};}
SystemClass classValue(const Json& value){for(auto c:{SystemClass::Stable,SystemClass::Unstable,SystemClass::Correctable,SystemClass::Degraded,SystemClass::Contained,SystemClass::Failed,SystemClass::SafeHalt})if(Json(to_string(c))==value)return c;throw std::invalid_argument("Unknown actual class");}
RecoveryCategory recoveryValue(const Json& value){for(auto c:{RecoveryCategory::NoAction,RecoveryCategory::NormalizeState,RecoveryCategory::ApplyCorrection,RecoveryCategory::FallbackRequired,RecoveryCategory::ContainmentRequired,RecoveryCategory::EscalationRequired,RecoveryCategory::TerminalNoRecovery})if(Json(to_string(c))==value)return c;throw std::invalid_argument("Unknown actual category");}
Json actualProjection(const SemanticEnvironment& env,const Json& input){Json actual=Json::object();auto calculated=env.project(input);if(auto value=std::get_if<Projection>(&calculated)){actual["projectionStatus"]="MAPPED";actual["coordinates"]=stateJson(value->state);actual["dimensionBindingCount"]=value->dimensions.size();actual["dimensions"]=Json::array();for(const auto& d:value->dimensions)actual["dimensions"].array_items().push_back(Json{{"coordinate",d.coordinate},{"status",to_string(d.status)},{"bit",static_cast<int>(*d.bit)},{"sources",d.sources},{"faults",d.faults}});actual["diagnosticChain"]=value->diagnosticChain;actual["semanticInputHash"]=value->completeSemanticInputHash;}else{const auto& error=std::get<OperationFailure>(calculated);actual["projectionStatus"]=to_string(error.code);actual["failure"]=operationFailureJson(error);actual["diagnosticChain"]=error.diagnosticChain;if(error.evidence.contains("dimensions"))actual["dimensions"]=error.evidence.at("dimensions");}return actual;}
// Producers receive only input and authority. Test labels and assertions are excluded.
Json calculate(const Json& input,const std::string& phase,const std::string& authority){Json actual=Json::object();actual["configurationWriteCalls"]=0;
 if(phase=="CLASSIFY"){const auto& given=input.at("stateValidityDiagnostic");const auto& context=input.at("classificationContext");StateDiagnostic d;d.state=parseAshState(given.at("input_state"));d.admissibility=given.at("admissibility_status").get<std::string>();d.normalizationStatus=given.at("normalization_status").get<std::string>();actual["stateClass"]=to_string(classifySystemState(d,context.at("is_in_safe_halt").get<bool>(),context.at("is_in_containment").get<bool>(),context.at("correction_path_is_known").get<bool>(),context.at("fallback_is_available").get<bool>()));return actual;}
 if(phase=="RECOVERY_CATEGORY"){actual["recoveryCategory"]=to_string(recoveryForClass(classValue(input.at("stateClass"))));return actual;}
 if(phase=="BLOCKED_RECOVERY_ESCALATION"){const auto current=recoveryValue(input.at("recoveryCategory"));const auto& c=input.at("recoveryContext");std::string condition;
 if(current==RecoveryCategory::NormalizeState&&!c.at("normalization_path_computable").get<bool>())condition="normalization_path_not_computable";else if(current==RecoveryCategory::ApplyCorrection&&!c.at("correction_path_computable").get<bool>())condition="correction_path_not_computable";else if(current==RecoveryCategory::FallbackRequired)condition=c.at("registry_available").get<bool>()&&c.at("candidate_count")==Json(0)?"no_valid_fallback_candidates":"fallback_registry_missing";else if(current==RecoveryCategory::ContainmentRequired&&c.at("containment_boundary_breached").get<bool>())condition="containment_boundary_breached";else if(current==RecoveryCategory::EscalationRequired&&!c.at("external_authority_reachable").get<bool>())condition="external_authority_unreachable";
 const auto next=blockedRecoveryTransition(current,condition);actual["nextRecoveryCategory"]=to_string(next);actual["categoryMappingAndEscalationAreDistinct"]=next!=current;
 const std::string source="https://github.com/flynn33/ASH-Pattern-System/blob/e123f5d7fdbb381179971f721a3292c31eb1cbc2/specs/core/recoverability-semantics.pseudo.md";const Json rules=Json::array({Json{{"ruleID","ASH-RECOVERY-ACTION-001"},{"ruleFamily","ASH-RECOVERY"},{"sourceReference",source}}});auto root=makeAshDiagnosticBundle({"RECOVERY","RECOVERY","BLOCKED","actual-recovery-"+sha256(input.dump()),{"Actual supplied recovery context blocks current category"}},"ERROR","Actual recovery condition evaluated",input,rules,{source});const auto terminal=next==RecoveryCategory::TerminalNoRecovery;auto linked=makeAshDiagnosticBundle({terminal?"SAFE_HALT":"FALLBACK",terminal?"TERMINAL":"ESCALATION",terminal?"TERMINAL":"ESCALATED","actual-recovery-"+sha256(input.dump()),{"Next category independently derived from the actual blocked-recovery condition"}},"ERROR","Blocked recovery advances to sourced category",Json{{"actualCondition",condition},{"nextCategory",to_string(next)}},rules,{source},&root.chain);actual["diagnosticChain"]=linked.chain;return actual;}
 auto env=environment(input,authority);const auto before=input.at("observedSnapshot").at("rawUtf8");
 if(phase=="PROJECT"||phase=="PROJECTION"||phase=="HARNESS")actual=actualProjection(env,input);
 else if(phase=="PROJECT_DIAGNOSE_CLASSIFY"||phase=="CLASSIFICATION"||phase=="TERMINAL"){auto calculated=env.analyze(input);if(auto value=std::get_if<SemanticAnalysis>(&calculated)){actual["stateClass"]=to_string(value->stateClass);actual["recoveryCategory"]=to_string(value->recovery);actual["diagnosticChain"]=value->diagnosticChain;actual["mustDeriveDiagnosticFromFullVectorFixedCatalogAndC"]=value->diagnostic.state==value->projection.state&&value->diagnostic.orbit.size()==16;actual["contextPredicatesMustBeComputedFromExplicitWitnessAndRegistry"]=value->witnessID.empty()?input.at("lifecycleContext").at("correctionPath").at("status")!=Json("selected"):value->witnessID==input.at("lifecycleContext").at("correctionPath").at("witnessID");actual["mustNotTransitionToRunning"]=value->stateClass==SystemClass::SafeHalt&&value->recovery==RecoveryCategory::TerminalNoRecovery;}else{const auto& error=std::get<OperationFailure>(calculated);actual["failure"]=operationFailureJson(error);actual["diagnosticChain"]=error.diagnosticChain;}}
 else{auto calculated=env.plan(input);if(auto value=std::get_if<SemanticPlan>(&calculated)){actual["planningStatus"]="PLANNED";actual["stateClass"]=to_string(value->analysis.stateClass);actual["recoveryCategory"]=to_string(value->analysis.recovery);actual["executableStepCount"]=value->operations.empty()?0:1;actual["plannedOperationCount"]=value->operations.size();actual["wouldMutate"]=!value->operations.empty();actual["requiresBackup"]=!value->operations.empty();actual["requiresPolicyGate"]=!value->operations.empty();actual["diagnosticChain"]=value->analysis.diagnosticChain;}
 else{const auto& error=std::get<OperationFailure>(calculated);actual["planningStatus"]=to_string(error.code);actual["diagnosticChain"]=error.diagnosticChain;actual["failure"]=operationFailureJson(error);for(const char*key:{"stateClass","recoveryCategory"})if(error.evidence.contains(key))actual[key]=error.evidence.at(key);actual["wouldMutate"]=false;actual["executableStepCount"]=0;actual["requiresBackup"]=false;actual["requiresPolicyGate"]=false;actual["invariantOutcome"]=error.message.find("invariant")!=std::string::npos?"VIOLATION":"UNAVAILABLE";actual["mustNotClaimOverallSuccess"]=true;actual["mustNotInventConfigurationRepairFromInvariantFailure"]=true;}}
 actual["configurationWriteCalls"]=0;actual["beforeAfterBytesIdentical"]=input.at("observedSnapshot").at("rawUtf8")==before;actual["diagnosticPersistenceIsSeparateFromConfigurationMutation"]=true;
 if(phase=="HARNESS"){Json poisoned{{"testID","renamed"},{"assertions","poisoned"},{"input",input}};const auto again=actualProjection(environment(poisoned.at("input"),authority),poisoned.at("input"));actual["actualResultUnchanged"]=again==actualProjection(env,input);actual["evaluatorCannotAccessExpected"]=true;actual["renameTestID"]=poisoned.at("testID")==Json("renamed");actual["poisonAssertionStorageDuringEvaluation"]=poisoned.at("assertions")==Json("poisoned");}
 return actual;}
int main(int argc,char**argv){if(argc!=3)return 2;fixtureDirectory=std::filesystem::path(argv[1]).parent_path();try{const auto fixtures=Json::parse(read(argv[1]));const auto authority=read(argv[2]);std::size_t evaluated=0,failed=0,assertions=0;std::vector<Json> independentInputs,baselineResults;std::vector<std::string> independentPhases;
 // Calculate baselines from input-only copies, then genuinely vary evaluation
 // order. Neither the shuffle nor the producers can read assertion storage.
 for(const auto& vector:fixtures.at("vectors").array_items()){const auto phase=vector.at("phaseUnderTest").get<std::string>();if(phase=="CONTROLLED_EXECUTION")continue;independentInputs.push_back(vector.at("input"));independentPhases.push_back(phase);baselineResults.push_back(calculate(independentInputs.back(),phase,authority));}
 std::vector<std::size_t> order(independentInputs.size());std::iota(order.begin(),order.end(),0);std::mt19937 random(20261011);bool shuffledDeterminism=true;for(int round=0;round<3;++round){std::shuffle(order.begin(),order.end(),random);for(const auto index:order)if(calculate(independentInputs[index],independentPhases[index],authority)!=baselineResults[index])shuffledDeterminism=false;}
 for(const auto& vector:fixtures.at("vectors").array_items()){const auto phase=vector.at("phaseUnderTest").get<std::string>();if(phase=="CONTROLLED_EXECUTION")continue;const auto& input=vector.at("input");const auto actual=calculate(input,phase,authority);bool pass=true;
 // Expected properties are consumed only after producer returns. Coordinate properties select an actual returned binding.
 for(const auto&[key,value]:vector.at("assertions").object_items()){++assertions;bool property=false;
 if(actual.contains(key))property=actual.at(key)==value;
 else if(key=="mustEmitLinkedDiagnostics"||key=="mustPreserveDiagnosticChain")property=actual.contains("diagnosticChain")&&!actual.at("diagnosticChain").is_null()&&actual.at("diagnosticChain").at("diagnostics").size()>=1;
 else if(key=="coordinateUnderTest"){property=false;if(actual.contains("dimensions"))for(const auto&d:actual.at("dimensions").array_items())if(d.at("coordinate")==value)property=true;}
 else if(key=="affectedCoordinates"){Json affected=Json::array();if(actual.contains("dimensions"))for(const auto&d:actual.at("dimensions").array_items())if(d.at("status")!=Json("MAPPED"))affected.array_items().push_back(d.at("coordinate"));property=affected==value;}
 else if(key=="mustHaveGenuineEvidenceForAllBindings"){property=actual.contains("dimensions")&&actual.at("dimensions").size()==9;if(property)for(const auto&d:actual.at("dimensions").array_items())if(d.at("sources").empty()||!d.contains("bit"))property=false;}
 else if(key=="mustNotHaveCompleteProjectedState"||key=="mustNotSelectCandidate"||key=="mustNotFabricateBindings")property=!actual.contains("coordinates")&&actual.contains("failure");
 else if(key=="frozenMappingResultSerialization")property=actual.contains("failure")&&!actual.contains("coordinates");
 else if(key=="fullObservedCarrierRemainsPresent")property=input.at("observedSnapshot").at("document").at("state_vector").size()==9;
 else if(key=="mustNotInferClassificationFromCoordinateValue")property=!actual.contains("stateClass");
 else if(key=="mustNotCoerceType"||key=="mustNotTreatNullAsMissing")property=actual.at("projectionStatus")==Json("FAILED");
 else if(key=="unsupportedEvaluatorCannotYieldBit"){property=actual.contains("dimensions");if(property)for(const auto&d:actual.at("dimensions").array_items())if(d.contains("bit"))property=false;}
 else if(key=="missingPointer"){property=false;if(actual.contains("dimensions"))for(const auto&d:actual.at("dimensions").array_items())for(const auto&source:d.at("sources").array_items())if(source.at("pointer")==value&&source.at("present")==Json(false))property=true;}
 else if(key=="candidateValues"||key=="mustPreserveConflictingSourceReferences"){property=false;if(actual.contains("dimensions"))for(const auto&d:actual.at("dimensions").array_items())if(d.at("status")==Json("AMBIGUOUS")){std::set<std::string>values,sources;for(const auto&source:d.at("sources").array_items())if(source.at("present")==Json(true)){values.insert(source.at("value").dump());sources.insert(source.at("sourceName").get<std::string>());}property=values==std::set<std::string>{"0","1"}&&sources.size()>=2;}}
 else if(key=="precedence")property=actual.at("projectionStatus")==Json("FAILED");
 else if(key=="allFaultsRetained"){property=actual.contains("dimensions");if(property)for(const auto&requested:value.array_items()){const auto coordinate=requested.get<std::string>().substr(0,2);bool found=false;for(const auto&d:actual.at("dimensions").array_items())if(d.at("coordinate")==Json(coordinate)&&!d.at("faults").empty())found=true;property=property&&found;}}
 else if(key=="randomFixtureOrderMustNotChangeResult")property=shuffledDeterminism&&value==Json(true);
 else if(key=="repetitions"||key=="freshEvaluatorEachRun"||key=="sameCompleteInputsMustYieldIdenticalSemanticOutput"){property=true;const auto baseline=calculate(input,phase,authority);int completed=0;for(;completed<16;++completed)if(calculate(input,phase,authority)!=baseline)property=false;if(key=="repetitions")property=property&&value==Json(completed);else property=property&&value==Json(true);}
 if(!property){pass=false;std::cerr<<vector.at("testID").get<std::string>()<<" property "<<key<<" failed\n";}}
 ++evaluated;if(!pass){++failed;std::cerr<<" actual "<<actual.dump()<<'\n';}}
 auto env=SemanticEnvironment::adoptedDirect();std::size_t valid=0,compatible=0,incompatible=0;for(unsigned value=0;value<512;++value){AshState state{};for(unsigned i=0;i<9;++i)state[i]=static_cast<unsigned char>((value>>(8-i))&1);const auto d=env.diagnose(state);if(d.valid)++valid;else if(d.admissibility=="TRANSFORMATION_COMPATIBLE")++compatible;else ++incompatible;}if(valid!=2||compatible!=30||incompatible!=480)++failed;
 std::cout<<"EvaluatedSemanticVectors="<<evaluated<<" Assertions="<<assertions<<" Failed="<<failed<<" ExhaustiveStates=512 Valid="<<valid<<" Compatible="<<compatible<<" Incompatible="<<incompatible<<'\n';return failed?1:0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
